<script setup lang="ts">
import {onMounted} from 'vue'
import {useGmWorkspace} from '../../stores/gm/useGmWorkspace'
import {useGmWorkspaceBindings} from '../../stores/gm/useGmWorkspace'
import {asyncPanel} from '../../asyncPanel'
import ItemCard from '../../components/ItemCard.vue'
import CurrencyRewardInputs from '../../components/CurrencyRewardInputs.vue'
import ItemQueue from '../../components/ItemQueue.vue'
import FieldError from '../../components/FieldError.vue'
const {giftHistory,fieldErrors,feedbackScope,busy,error,notice,page,search,rows,action,message,giftCurrencies,giftTitle,giftAttachments,pendingId,category,giftGold,giftMessage,giftCategory,giftName,giftId,giftVersion,giftEnabled,currencyNames,money,run,load,searchRows,select,saveGift,resetGift,editGift,copyGift,useGift,giftEditing,openPicker}=useGmWorkspaceBindings()

const workspace=useGmWorkspace()
onMounted(()=>workspace.activate('gifts'))
</script>
<template><div class="gm-workspace"><section class="panel"><div class="section-title"><h2>礼包模板</h2><button class="primary" :disabled="busy||!!pendingId" @click="resetGift">新建礼包</button></div><form class="toolbar" @submit.prevent="searchRows"><input v-model="search" aria-label="搜索条件" placeholder="模板名称或编号" :disabled="busy"><input v-model="category" aria-label="礼包分类筛选" placeholder="分类（留空显示全部）" maxlength="32" :disabled="busy"><button :disabled="busy">查询</button></form><div class="gift-grid"><article v-for="r in rows" :key="r.id" class="gift-card"><div class="section-title"><span class="gift-icon">◇</span><span class="status-badge" :class="r.enabled?'success':'neutral'">{{r.enabled?'已启用':'已停用'}}</span></div><h3>{{r.name}}</h3><small class="muted">#{{r.id}} · v{{r.current_version}} · {{r.rewards?.items?.length||0}} 条附件</small><p v-for="(value,coin) in r.rewards?.currency_rewards||{}" :key="coin">{{currencyNames[coin]||coin}} {{money(value)}}</p><p v-if="r.rewards?.gold">金币 {{money(r.rewards.gold)}}</p><small v-if="r.rewards?.category" class="pill">{{r.rewards.category}}</small><ul class="gift-items"><li v-for="i in r.rewards?.items||[]" :key="i.id"><ItemCard :item="i"/><b>×{{i.quantity}}</b></li></ul><div class="button-row"><button :disabled="busy||!!pendingId" @click="editGift(r)">编辑版本</button><button :disabled="busy||!!pendingId" @click="copyGift(r)">复制模板</button><button :disabled="busy" @click="giftHistory=r.id">版本对比</button><button class="primary" :disabled="busy||!r.enabled||!!pendingId" @click="useGift(r)">用于发放</button></div></article></div><p v-if="!rows.length&&!busy" class="empty">暂无模板。新建一个礼包，将常用奖励组合保存。</p><div class="pagination"><button :disabled="page===1||busy" @click="page--;run(load)">上一页</button><span>第 {{page}} 页</span><button :disabled="rows.length<50||busy" @click="page++;run(load)">下一页</button></div></section><section v-if="giftEditing" class="panel" id="gift-editor"><div class="section-title"><h2>{{giftId?'编辑礼包 #'+giftId:'新建礼包模板'}}</h2><span class="pill">{{giftId?'当前 v'+giftVersion:'独立模板草稿'}}</span></div><p class="field-hint">模板草稿与邮件草稿分别保存，不会互相覆盖。每次修改生成不可变版本，停用不删除历史。</p><div class="form-grid"><label><span>模板名称 <em class="required-tag">必填</em></span><input id="gift-name" v-model="giftName" maxlength="80" aria-required="true" :aria-invalid="!!fieldErrors['gift-name']" :aria-describedby="fieldErrors['gift-name']?'gift-name-error':undefined" :disabled="busy"><FieldError id="gift-name-error" :message="fieldErrors['gift-name']"/></label><label>模板状态<select v-model="giftEnabled" :disabled="busy"><option :value="true">启用</option><option :value="false">停用</option></select></label></div><div class="form-grid"><label>金币附件<input id="gift-gold" v-model.number="giftGold" type="number" min="0" max="1000000000" :disabled="busy"><FieldError id="gift-gold-error" :message="fieldErrors['gift-gold']"/></label><label><span>邮件标题 <small>可选，作为正文首行发送</small></span><input id="gift-title" v-model="giftTitle" maxlength="40" aria-label="礼包邮件标题" :disabled="busy||!!pendingId" :aria-invalid="!!fieldErrors['gift-title']" :aria-describedby="fieldErrors['gift-title']?'gift-title-error':undefined"><FieldError id="gift-title-error" :message="fieldErrors['gift-title']"/></label><label>邮件文字<input id="gift-message" v-model="giftMessage" maxlength="60" :disabled="busy"><FieldError id="gift-message-error" :message="fieldErrors['gift-message']"/></label><label>分类<input v-model="giftCategory" maxlength="32" placeholder="新手 / 活动 / 补偿 / 测试" :disabled="busy"></label></div><p class="field-hint">可保存纯金币礼包；邮件文字和金币一起绑定版本。修改发放草稿时解除绑定，不改动原模板。</p><div class="section-title"><h3>礼包附件 · {{giftAttachments.length}} / 20</h3><button :disabled="busy" @click="openPicker">添加物品</button></div><CurrencyRewardInputs v-model="giftCurrencies" prefix="gift" :busy="busy||!!pendingId" :errors="fieldErrors"/><div id="gift-items" tabindex="-1" :aria-invalid="!!fieldErrors['gift-items']" :aria-describedby="fieldErrors['gift-items']?'gift-items-error':undefined"><FieldError id="gift-items-error" :message="fieldErrors['gift-items']"/><ItemQueue prefix="gift" :errors="fieldErrors" :items="giftAttachments" :busy="busy" @quantity="(n,v)=>giftAttachments[n].quantity=v" @remove="n=>giftAttachments.splice(n,1)"/></div><p v-if="error&&feedbackScope==='gift'" class="submit-error">{{error}}</p><p v-else-if="notice&&feedbackScope==='gift'" class="submit-success">{{notice}}</p><div class="action-footer"><span class="muted">保存模板不会发放物品。</span><div class="button-row"><button :disabled="busy||!!pendingId" @click="resetGift">重置为新模板</button><button class="primary" :disabled="busy" @click="saveGift">{{giftId?'保存为新版本':'创建礼包模板'}}</button></div></div></section></div></template>
